using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using LocalUsageValidation;
public static class Tests {
 static string root;static int passed,failed;static DateTimeOffset now=new DateTimeOffset(2026,10,29,12,0,0,TimeSpan.Zero);
 static string C(string id,string req,string at,long i,long o,long cr,long cc){return "{\"type\":\"assistant\",\"timestamp\":\""+at+"\",\"requestId\":\""+req+"\",\"message\":{\"id\":\""+id+"\",\"content\":\"SECRET_DO_NOT_OUTPUT\",\"usage\":{\"input_tokens\":"+i+",\"output_tokens\":"+o+",\"cache_read_input_tokens\":"+cr+",\"cache_creation_input_tokens\":"+cc+",\"iterations\":[{\"output_tokens\":999}],\"output_tokens_details\":{\"thinking_tokens\":999}}}}";}
 static string A(int step,int i,int o,int c){return "{\"type\":\"PLANNER_RESPONSE\",\"status\":\"DONE\",\"step_index\":"+step+",\"created_at\":\"2026-10-29T00:00:00Z\",\"input_tokens\":"+i+",\"output_tokens\":"+o+",\"cache_read_tokens\":"+c+"}";}
 static string Turn(int n,string at,int i,int o,int cache,int reason){return "{\"turnNumber\":"+n+",\"endedAt\":\""+at+"\",\"inputTokens\":"+i+",\"outputTokens\":"+o+",\"cachedReadTokens\":"+cache+",\"reasoningTokens\":"+reason+",\"totalTokens\":"+(i+o)+"}";}
 static string G(string turns,int sum){return "{\"sessionId\":\"private-session\",\"session\":{\"totalTokens\":"+sum+"},\"turns\":["+turns+"]}";}
 static string Dir(string name){string p=Path.Combine(root,name);Directory.CreateDirectory(p);return p;}
 static void Write(string dir,string rel,string text){string p=Path.Combine(dir,rel);Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,text,new UTF8Encoding(false));}
 static Collector New(){return new Collector(new Options{Timezone=TimeZoneInfo.Utc});}
 static void Assert(bool value){if(!value)throw new Exception("assertion_failed");}
 static void Test(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+" "+ex.GetType().Name);}}
 public static int Main(string[] args){Collector.InitializePathHandling();if(args.Length!=1)return 2;root=Collector.NormalizeRoot(Path.Combine(Path.GetFullPath(args[0]),"fixtures-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(root);try{
 string at="2026-10-29T00:00:00Z",line=C("m","r",at,10,5,20,30);
 Test("claude_duplicate_blocks_and_copies",delegate{string d=Dir("c1");Write(d,"a.jsonl",line+"\n"+line+"\n");Write(d,"sub\\b.jsonl",line+"\n");Result r=New().Collect("claude",d,now);Assert(r.totals.total==65&&r.totals.requests==1&&r.coverage.duplicateRecords==2&&!r.coverage.partial);});
 Test("duplicate_block_timestamp_drift",delegate{string d=Dir("drift");Write(d,"a.jsonl",line+"\n"+C("m","r","2026-10-29T00:00:01Z",10,5,20,30));Result r=New().Collect("claude",d,now);Assert(r.totals.total==65&&r.coverage.duplicateRecords==1&&!r.coverage.partial);});
 Test("claude_stream_output_growth_earliest_date",delegate{string d=Dir("stream");Write(d,"a.jsonl",C("m","r","2026-10-28T23:59:59Z",10,1,20,30)+"\n"+C("m","r",at,10,5,20,30));Result r=New().Collect("claude",d,now);Assert(r.totals.total==65&&!r.coverage.partial&&r.days.Find(x=>x.date=="2026-10-28").total==65);});
 Test("claude_missing_ids",delegate{string d=Dir("c2");Write(d,"a.jsonl",C("","r",at,1,1,0,0)+"\n"+C("m","",at,1,1,0,0)+"\n");Result r=New().Collect("claude",d,now);Assert(r.coverage.invalidRecords==2&&r.coverage.partial&&r.totals.total==0);});
 Test("claude_cached_split_nested_excluded",delegate{string d=Dir("c3");Write(d,"a.jsonl",line);Result r=New().Collect("claude",d,now);Assert(r.totals.input==10&&r.totals.cacheRead==20&&r.totals.cacheCreate==30&&r.totals.output==5&&r.totals.total==65);});
 Test("negative_rejected",delegate{string d=Dir("c4");Write(d,"a.jsonl",C("m","r",at,-1,2,0,0));Result r=New().Collect("claude",d,now);Assert(r.coverage.invalidRecords==1&&r.coverage.partial);});
 Test("record_overflow_rejected",delegate{string d=Dir("c5");Write(d,"a.jsonl",C("m","r",at,long.MaxValue,1,0,0));Result r=New().Collect("claude",d,now);Assert(r.coverage.invalidRecords==1&&r.totals.total==0);});
 Test("aggregate_overflow_atomic",delegate{string d=Dir("c6");Write(d,"a.jsonl",C("m","r",at,long.MaxValue,0,0,0)+"\n"+C("n","s",at,1,0,0,0));Result r=New().Collect("claude",d,now);Assert(r.totals.total==long.MaxValue&&r.totals.requests==1&&r.coverage.partial);});
 Test("grok_subsets_not_added",delegate{string d=Dir("g1");Write(d,"s\\usage.json",G(Turn(1,at,100,20,80,10),120));Result r=New().Collect("grok",d,now);Assert(r.totals.total==120&&r.totals.cacheRead==80&&r.totals.reasoning==10&&!r.coverage.partial);});
 Test("grok_multiturn_daily_and_old_session",delegate{string d=Dir("g2");Write(d,"usage.json",G(Turn(1,"2026-09-01T00:00:00Z",100,10,0,0)+","+Turn(2,at,20,2,0,0)+","+Turn(3,"2026-10-28T00:00:00Z",30,3,0,0),165));Result r=New().Collect("grok",d,now);Assert(r.totals.total==55&&r.totals.requests==2&&r.coverage.totalMismatches==0&&r.days.Find(x=>x.date=="2026-10-28").total==33);});
 Test("grok_crossfile_dedup",delegate{string d=Dir("g3"),g=G(Turn(1,at,1,2,0,0),3);Write(d,"a\\usage.json",g);Write(d,"b\\usage.json",g);Result r=New().Collect("grok",d,now);Assert(r.totals.total==3&&r.coverage.duplicateRecords==1);});
 Test("grok_no_turn_history",delegate{string d=Dir("g4");Write(d,"usage.json",G("",200));Result r=New().Collect("grok",d,now);Assert(r.status=="unsupported_no_history"&&r.coverage.partial&&r.totals==null&&r.days.Count==0);});
 Test("grok_total_mismatch_diagnostic",delegate{string d=Dir("g5");Write(d,"usage.json",G(Turn(1,at,1,2,0,0).Replace("\"totalTokens\":3","\"totalTokens\":4"),20));Result r=New().Collect("grok",d,now);Assert(r.totals.total==3&&r.coverage.totalMismatches==2&&r.coverage.partial);});
 Test("ag_canonical_only_and_duplicate_steps",delegate{string d=Dir("a1"),a=A(0,278,4,30214);Write(d,"conv\\.system_generated\\logs\\transcript_full.jsonl",a+"\n"+a);Write(d,"conv\\.system_generated\\logs\\transcript.jsonl",A(1,100,2,9));Write(d,"conv\\.system_generated\\logs\\chunks\\transcript_full\\x.jsonl",A(2,100,2,9));Result r=New().Collect("antigravity",d,now);Assert(r.coverage.filesFound==1&&r.coverage.duplicateRecords==1&&r.totals.total==282&&r.totals.cacheRead==30214);});
 Test("ag_conflict_flag",delegate{string d=Dir("a2");Write(d,"conv\\.system_generated\\logs\\transcript_full.jsonl",A(0,2,3,4)+"\n"+A(0,4,3,4));Result r=New().Collect("antigravity",d,now);Assert(r.coverage.conflictingRecords==1&&r.coverage.partial&&r.totals.total==5);});
 Test("missing_root_not_zero",delegate{Result r=New().Collect("claude",Path.Combine(root,"missing"),now);Assert(r.status=="no_data"&&r.totals==null&&r.days.Count==0);});
 Test("malformed_token_record",delegate{string d=Dir("bad1");Write(d,"a.jsonl","{\"type\":\"assistant\",\"usage\":broken}\n");Result r=New().Collect("claude",d,now);Assert(r.coverage.invalidRecords==1&&r.coverage.partial);});
 Test("overlong_line_recovery",delegate{string d=Dir("bad2");Write(d,"a.jsonl",new string('x',600)+"\n"+line+"\n");Result r=new Collector(new Options{Timezone=TimeZoneInfo.Utc,MaxLineBytes=512}).Collect("claude",d,now);Assert(r.coverage.invalidRecords==1&&r.coverage.partial&&r.totals.total==65);});
 Test("incomplete_tail_then_append",delegate{string d=Dir("tail");Write(d,"a.jsonl",line+"\n{\"type\":\"assistant\",\"usage\":");Collector c=New();Result r=c.Collect("claude",d,now);Assert(r.coverage.incompleteRecords==1&&r.coverage.partial&&r.totals.total==65);Write(d,"a.jsonl",line+"\n"+C("new","new",at,1,2,0,0));r=c.Collect("claude",d,now);Assert(r.totals.total==68&&!r.coverage.partial&&r.coverage.cacheHits==0);});
 Test("cache_hit_then_append_change_truncate",delegate{string d=Dir("cache");Write(d,"a.jsonl",line+"\n");Collector c=New();c.Collect("claude",d,now);Result r=c.Collect("claude",d,now);Assert(r.coverage.cacheHits==1&&r.coverage.bytesRead==0);File.AppendAllText(Path.Combine(d,"a.jsonl"),C("n","n",at,1,2,0,0)+"\n");r=c.Collect("claude",d,now);Assert(r.totals.total==68&&r.coverage.cacheHits==0);Write(d,"a.jsonl",C("x","x",at,2,3,0,0));r=c.Collect("claude",d,now);Assert(r.totals.total==5&&r.coverage.cacheHits==0);Write(d,"a.jsonl","");r=c.Collect("claude",d,now);Assert(r.totals.total==0&&r.coverage.cacheHits==0);});
 Test("local_calendar_inclusive_30_days",delegate{string d=Dir("dates");Write(d,"a.jsonl",C("a","a","2026-09-30T14:59:59Z",1,0,0,0)+"\n"+C("b","b","2026-09-30T15:00:00Z",2,0,0,0)+"\n"+C("c","c","2026-10-29T15:00:00Z",4,0,0,0));TimeZoneInfo tz=TimeZoneInfo.CreateCustomTimeZone("UTC+09",TimeSpan.FromHours(9),"UTC+09","UTC+09");Result r=new Collector(new Options{Timezone=tz}).Collect("claude",d,now);Assert(r.from=="2026-09-30"&&r.to=="2026-10-29"&&r.totals.total==3&&r.days.Count==30);});
 Test("file_size_cap",delegate{string d=Dir("cap1");Write(d,"a.jsonl",line);Result r=new Collector(new Options{MaxFileBytes=16}).Collect("claude",d,now);Assert(r.coverage.partial&&r.coverage.skippedFiles==1&&r.coverage.bytesRead==0);});
 Test("total_read_cap",delegate{string d=Dir("cap2");Write(d,"a.jsonl",line);Result r=new Collector(new Options{MaxBytes=20}).Collect("claude",d,now);Assert(r.coverage.partial&&r.coverage.limitReached&&r.coverage.bytesRead<=20);});
 Test("file_count_cap",delegate{string d=Dir("cap3");Write(d,"a.jsonl",line);Write(d,"b.jsonl",line);Result r=new Collector(new Options{MaxFiles=1}).Collect("claude",d,now);Assert(r.coverage.partial&&r.coverage.limitReached&&r.coverage.filesRead<=1);});
 Test("private_content_not_serialized",delegate{string d=Dir("privacy");Write(d,"a.jsonl",line);string s=new JavaScriptSerializer().Serialize(New().Collect("claude",d,now));Assert(!s.Contains("SECRET_DO_NOT_OUTPUT")&&!s.Contains(root)&&!s.Contains("requestId")&&!s.Contains("message"));});
 Test("required_timestamp_not_mtime",delegate{string d=Dir("stamp");Write(d,"a.jsonl",C("m","r","2026-10-29T01:02:03",1,1,0,0));Result r=New().Collect("claude",d,now);Assert(r.coverage.partial&&r.totals.total==0);});
 Test("claude_summary_not_added",delegate{string d=Dir("summary");Write(d,"a.jsonl",line+"\n{\"type\":\"cost-state\",\"modelUsage\":{\"totalTokens\":999999}}\n");Result r=New().Collect("claude",d,now);Assert(r.totals.total==65);});
 Test("conflicting_claude_not_silent_max",delegate{string d=Dir("conflict");Write(d,"a.jsonl",line+"\n"+C("m","r",at,99,5,20,30));Result r=New().Collect("claude",d,now);Assert(r.coverage.conflictingRecords==1&&r.coverage.partial&&r.totals.total==65);});
 Test("same_size_mtime_change_invalidates",delegate{string d=Dir("mtime");Write(d,"a.jsonl",C("m","r",at,1,2,0,0));Collector c=New();c.Collect("claude",d,now);Write(d,"a.jsonl",C("m","r",at,2,2,0,0));File.SetLastWriteTimeUtc(Path.Combine(d,"a.jsonl"),DateTime.UtcNow.AddMinutes(1));Result r=c.Collect("claude",d,now);Assert(r.coverage.cacheHits==0&&r.totals.total==4);});
 Test("newest_file_first",delegate{string d=Dir("newest");Write(d,"old.jsonl",line);Write(d,"new.jsonl",C("x","x",at,1,1,0,0)+"\n");File.SetLastWriteTimeUtc(Path.Combine(d,"old.jsonl"),DateTime.UtcNow.AddDays(-1));Result r=new Collector(new Options{MaxBytes=400}).Collect("claude",d,now);Assert(r.totals.total==2&&r.coverage.partial);});
 Test("projection_excludes_private_content",delegate{string p=JsonProjection.Project(line,"claude");Assert(!p.Contains("SECRET_DO_NOT_OUTPUT")&&!p.Contains("iterations")&&p.Contains("input_tokens"));});
 Test("projection_escaped_quote_payload",delegate{string raw=line.Replace("SECRET_DO_NOT_OUTPUT","SECRET_\\\"usage\\\":999");string p=JsonProjection.Project(raw,"claude");Assert(!p.Contains("SECRET_")&&new JavaScriptSerializer().DeserializeObject(p)!=null);});
 Test("projection_escaped_key",delegate{string raw=line.Replace("requestId","request\\u0049d");string p=JsonProjection.Project(raw,"claude");Assert(p.Contains("requestId"));});
 Test("projection_validates_ignored_value",delegate{bool rejected=false;try{JsonProjection.Project(line.Replace("\"SECRET_DO_NOT_OUTPUT\"","[1,]"),"claude");}catch(FormatException){rejected=true;}Assert(rejected);});
 Test("projection_rejects_trailing_json",delegate{bool rejected=false;try{JsonProjection.Project(line+"{}","claude");}catch(FormatException){rejected=true;}Assert(rejected);});
 Test("ag_missing_meter_not_zero",delegate{string d=Dir("unmetered");Write(d,"conv\\.system_generated\\logs\\transcript_full.jsonl","{\"type\":\"PLANNER_RESPONSE\",\"status\":\"DONE\",\"step_index\":1,\"created_at\":\"2026-10-29T00:00:00Z\"}");Result r=New().Collect("antigravity",d,now);Assert(r.coverage.unmeteredRecords==1&&r.coverage.invalidRecords==0&&r.coverage.partial);});
 Test("stable_invalid_file_is_cached",delegate{string d=Dir("badcache");Write(d,"a.jsonl","{\"type\":\"assistant\",\"usage\":broken}\n");Collector c=New();c.Collect("claude",d,now);Result r=c.Collect("claude",d,now);Assert(r.coverage.invalidRecords==1&&r.coverage.cacheHits==1&&r.coverage.bytesRead==0&&r.coverage.partial);});
 Test("grok_long_path_and_ignore_unrelated_children",delegate{string d=Dir("longpath");string rel=new string('p',160)+"\\"+new string('s',120)+"\\usage.json";Write(d,rel,G(Turn(1,at,1,2,0,0),3));Write(d,"p\\s\\irrelevant\\usage.json",G(Turn(1,at,900,1,0,0),901));Result r=New().Collect("grok",d,now);Assert(r.coverage.filesFound==1&&r.totals.total==3&&!r.coverage.partial);});
 Test("same_length_restored_mtime_invalidates",delegate{string d=Dir("restored");Write(d,"a.jsonl",C("m","r",at,1,2,0,0));string f=Path.Combine(d,"a.jsonl");DateTime before=File.GetLastWriteTimeUtc(f);Collector c=New();c.Collect("claude",d,now);Write(d,"a.jsonl",C("m","r",at,2,2,0,0));File.SetLastWriteTimeUtc(f,before);Result r=c.Collect("claude",d,now);Assert(r.coverage.cacheHits==0&&r.totals.total==4);});
 Test("opened_handle_outside_root_rejected",delegate{string allowed=Dir("allowed"),outside=Dir("outside");Write(outside,"a.jsonl",line);bool rejected=false;using(var stream=new FileStream(Path.Combine(outside,"a.jsonl"),FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){try{FileSafety.Validate(stream,allowed);}catch(IOException){rejected=true;}}Assert(rejected);});
 }finally{try{Directory.Delete(root,true);}catch{failed++;Console.WriteLine("FAIL fixture_cleanup");}}Console.WriteLine("RESULT passed="+passed+" failed="+failed);return failed==0?0:1;}
}
